        function delayAniClass(target, delay) {
            setTimeout(function() {
                target.addClass('on');
            }, delay);
        }

        var widgetList = $(this).parent().siblings().find('.widget_list > .widget_box');
        var widgetListIdx = $(widgetList).length;

        if (wwidth > 480) {
            $($(this).parent().siblings().find('.widget_list')).masonry({
